const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const url = (b, s = '') => b.includes('?') ? b + encodeURIComponent(s) : b + (s ? '/' + s : '');
const canon = slug => absUrl(slug);
const ext = (u, t) => /^https?:\/\//.test(u || '') ? `<a href="${esc(u)}" rel="nofollow noopener" target="_blank">${esc(t)}</a>` : esc(t);
const host = u => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch { return ''; } };
const kort = naam => String(naam).replace(/\s*\(.*\)\s*$/, '').trim() || String(naam);
const num = (n, language) => language === 'en' ? Number(n).toFixed(2) : Number(n).toFixed(2).replace('.', ',');
const LANGS = ['en', 'nl', 'de'];
export const PROVIDER_DATE = '2026-11-17';

