// ---- welke aanbieders een pagina hebben ----
const BASE_LISTS = () => Object.values(LIJSTEN).filter(l => !l.catalog);
let cache = null;
export function providerEntries() {
  if (cache) return cache;
  const out = [], seen = new Set();
  for (const list of BASE_LISTS()) for (const provider of list.klinieken || []) {
    if (!heeftPagina(list.id, provider)) continue;
    const slugs = Object.fromEntries(LANGS.map(language => [language, providerSlug(provider, language)]));
    if (seen.has(slugs.en)) continue; // twee aanbieders met dezelfde naam: alleen de eerste krijgt het adres
    seen.add(slugs.en);
    out.push({ list, provider, slugs });
  }
  return cache = out;
}
export const PROVIDER_SLUGS = () => Object.fromEntries(providerEntries().flatMap(e => LANGS.map(language => [e.slugs[language], { entry: e, taal: language }])));

function position(list, provider) {
  const clinics = reviewRanking(list), doctors = reviewRanking(list, 'doctor');
  const mine = r => r.k.id === provider.id || String(r.k.id).startsWith(provider.id + '-doctor-');
  for (const [ranking, cohort] of [[clinics, 'clinics'], [doctors, 'doctors']]) {
    const i = ranking.ranked.findIndex(mine);
    if (i >= 0) return { cohort, place: i + 1, total: ranking.ranked.length, review: ranking.ranked[i].review };
  }
  const row = [...clinics.unranked, ...doctors.unranked].find(mine);
  return { cohort: null, review: row ? row.review : null };
}

const costGuide = (list, language) => Object.entries(PAGES).find(([, p]) => p.taal === language && p.ingreep === list.ingreep && (p.naar === list.naar || p.naar === 'abroad')) || Object.entries(PAGES).find(([, p]) => p.taal === language && p.ingreep === list.ingreep);

function figures(provider, t, language) {
  const sources = reviewSources(provider), rows = [...sources.included, ...sources.excluded];
  if (!rows.length) return `<p>${esc(t.noReviews)}</p>`;
  const why = r => r.reason === 'different_entity_scope' && provider.kind !== 'doctor' ? t.excluded.different_entity_scope_clinic : t.excluded[r.reason];
  return `<div class="sr-table"><table><thead><tr><th>${esc(t.platform)}</th><th>${esc(t.score)}</th><th>${esc(t.count)}</th><th>${esc(t.date)}</th><th>${esc(t.counted)}</th></tr></thead><tbody>${rows.map(r => {
    const warn = waarschuwingTekst(r.waarschuwing, language);
    return `<tr><th scope="row">${ext(r.bron, r.platform || host(r.bron))}${warn ? `<br><small>${esc(warn)}</small>` : ''}</th><td>${r.score == null ? '?' : esc(String(r.score).replace('.', language === 'en' ? '.' : ',')) + '/' + esc(r.max || 5)}</td><td>${esc(r.aantal == null ? '?' : r.aantal)}</td><td>${esc(r.datum || '?')}</td><td>${r.included ? esc(t.yes) : esc(t.no) + (why(r) ? ': ' + esc(why(r)) : '')}</td></tr>`;
  }).join('')}</tbody></table></div>`;
}

// ---- pagina per aanbieder ----
export function providerPage(base, entry, language) {
  const { list, provider: k, slugs } = entry, t = T[language], o = k.openheid || {}, slug = slugs[language];
  const name = k.naam, short = kort(name), pos = position(list, k), rankSlug = list.slugs[language] || list.slugs.en, rankTitle = choiceTitle(list, language).split(': ')[0];
  const place = [k.stad, countryName(k.land || list.land, language)].filter(Boolean).join(', ');
  const conclusion = conclusieTekst(list.id, k, language);
  const prijs = veldTekst(list.id, k.id, 'prijs', language), arts = veldTekst(list.id, k.id, 'arts', language), gar = veldTekst(list.id, k.id, 'gar', language);
  const risks = (k.risico || []).map((r, i) => ({ ...r, tekst: veldTekst(list.id, k.id, 'risico:' + i, language) })).filter(r => r.tekst && r.bron);
  const staff = (k.artsen || []).filter(a => a.naam && a.bron), proof = choiceRows({ ...list, klinieken: [k] })[0];
  const mentions = (k.vermeld || []).filter(u => /^https?:\/\//.test(u));
  const context = procedureContext(list.ingreep, language), guide = costGuide(list, language);
  const ring = providerEntries().filter(e => e.list.id === list.id).sort((a, b) => a.slugs.en < b.slugs.en ? -1 : 1), self = ring.findIndex(e => e.provider.id === k.id), others = ring.filter(e => e.provider.id !== k.id);
  const near = ring.length > 1 && self >= 0 ? [1, 2, 3, -1, -2, -3].map(d => ring[(self + d + ring.length * 3) % ring.length]).filter((e, i, a) => e.provider.id !== k.id && a.indexOf(e) === i) : [];
  const included = pos.review ? pos.review.sources.included.filter(r => r.score != null && r.aantal != null && r.platform) : [];
  const reviewLine = included.length ? included.map(r => `${r.platform} ${String(r.score).replace('.', language === 'en' ? '.' : ',')}/${r.max || 5} (${r.aantal})`).join(', ') : t.noReviews.replace(/\.$/, '');
  const organizationEntity = list.id === 'hair-turkey' && (k.id === 'aygin' || k.id === 'cinik');
  const placed = pos.cohort && pos.total >= 3;
  const rankLine = pos.cohort ? `${t.index} ${num(pos.review.score, language)}/5.${placed ? ` ${t.rankedAs(pos.place, pos.total, t[pos.cohort])} ${rankTitle}.` : ''}` : `${t.notRanked}. ${pos.review && pos.review.held ? t.heldWhy : t.notRankedWhy}`;
  const faq = [
    { q: t.qLegit(short), a: `${reviewLine}. ${rankLine} ${t.read} ${list.gecontroleerd}.` },
    { q: t.qCost(short), a: prijs || t.noPrice },
    ...(arts ? [{ q: t.qWho(short), a: arts }] : []),
    ...(risks.length ? [{ q: t.qIncident(short), a: risks.map(r => r.tekst).join(' ') }] : []),
  ];
  const body = `<div class="s-choice pv"><p class="sr-breadcrumb"><a href="${esc(url(base, language === 'en' ? '' : language))}">${esc(t.home)}</a> / <a href="${esc(url(base, rankSlug))}">${esc(rankTitle)}</a></p>` +
    `<h1>${esc(name)}: ${esc(t.h1End)}</h1><p class="sr-muted">${esc(place)} · ${esc(procedureLabel(list.ingreep, language))} · <time datetime="${esc(list.gecontroleerd)}">${esc(t.read)} ${esc(list.gecontroleerd)}</time></p>` +
    `<div class="answer"><p><strong>${esc(t.found)}.</strong> ${esc(conclusion)}</p><p>${pos.cohort ? `<strong>${esc(t.index)} ${num(pos.review.score, language)}/5.</strong> ${placed ? esc(t.rankedAs(pos.place, pos.total, t[pos.cohort])) + ' ' : ''}<a href="${esc(url(base, rankSlug))}">${esc(rankTitle)}</a>.` : `<strong>${esc(t.notRanked)}.</strong> ${esc(pos.review && pos.review.held ? t.heldWhy : t.notRankedWhy)}`}</p></div>` +
    `<h2>${esc(t.figures)}</h2>${figures(k, t, language)}` +
    `<h2>${esc(t.price)}</h2><p>${prijs ? esc(prijs) + (o.prijs_bron ? ' ' + ext(o.prijs_bron, t.priceSource) : '') : esc(t.noPrice)}</p>` +
    `<h2>${esc(t.who)}</h2><p>${arts ? esc(arts) + (o.arts_bron ? ' ' + ext(o.arts_bron, t.whoSource) : '') : esc(t.noWho)}</p>` +
    (gar ? `<h2>${esc(t.guarantee)}</h2><p>${esc(gar)}${o.garantie_bron ? ' ' + ext(o.garantie_bron, t.whoSource) : ''}</p>` : '') +
    (staff.length ? `<h2>${esc(t.staff)}</h2><ul>${staff.map(a => `<li>${ext(a.bron, a.naam)}${a.titel ? ' <span class="sr-muted">' + esc(a.titel) + '</span>' : ''}</li>`).join('')}</ul><p class="sr-muted">${esc(t.staffNote)}</p>` : '') +
    `<h2>${esc(t.qual)}</h2><p>${proof.q.length ? proof.q.map(q => ext(q.url, q.label)).join(' · ') : esc(t.noQual)}</p>` +
    (risks.length ? `<h2>${esc(t.incidents)}</h2><ul>${risks.map(r => `<li>${esc(r.tekst)} ${ext(r.bron, host(r.bron))}${r.datum ? ' · ' + esc(r.datum) : ''}</li>`).join('')}</ul>` : '') +
    (mentions.length ? `<h2>${esc(t.mentions)}</h2><ul>${mentions.map(u => `<li>${ext(u, host(u))}</li>`).join('')}</ul>` : '') +
    (context ? `<h2>${esc(t.ask)}</h2><ol>${context.questions.map(q => '<li>' + esc(q) + '</li>').join('')}</ol><p class="sr-muted">${ext(context.source, t.askSource)}</p>` : '') +
    `<h2>${esc(t.more)}</h2><ul><li><a href="${esc(url(base, rankSlug))}">${esc(t.ranking)}: ${esc(rankTitle)}</a></li>${guide ? `<li><a href="${esc(url(base, guide[0]))}">${esc(t.cost)}: ${esc(guide[1].h1)}</a></li>` : ''}${CHECK[list.naar] ? `<li><a href="${esc(url(base, 'check-surgeon-' + list.naar))}"${language === 'en' ? '' : ' hreflang="en"'}>${esc(t.check)} ${esc(countryName(list.land, language))}${language === 'en' ? '' : ' (English)'}</a></li>` : ''}${/^https?:\/\//.test(k.site || '') ? `<li>${ext(k.site, t.site)}</li>` : ''}</ul>` +
    (near.length || compareLinks(base, entry, language) ? `<h2>${esc(t.others)}</h2><ul>${compareLinks(base, entry, language)}${near.map(e => `<li><a href="${esc(url(base, e.slugs[language]))}">${esc(e.provider.naam)}</a></li>`).join('')}</ul>` : '') +
    `<section id="vragen"><h2>${esc(t.faq)}</h2>${faq.map(f => `<details><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join('')}</section>` +
    `<p class="sr-note">${esc(t.limits)} <a href="${esc(url(base, aboutSlug(language)))}">${esc(t.method)}</a>. ${esc(t.correction)} <a href="mailto:${CONTACT}">${CONTACT}</a>.</p><!--sc-help--><!--sc-mail--></div>`;
  const title = [`${short} ${t.titleEnd}`, `${short}: ${t.h1End}`, `${short} ${t.titleEnd.split(':')[0]}`].find(x => x.length <= 60) || `${short} ${t.titleEnd.split(':')[0]}`, desc = knip(`${short}: ${t.descEnd} ${list.gecontroleerd}.`);
  const ld = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'Organization', '@id': SITE.base + '#org', name: SITE.name, url: SITE.base },
    { '@type': 'Article', headline: `${name}: ${t.h1End}`, description: desc, inLanguage: language, datePublished: PROVIDER_DATE, dateModified: list.gecontroleerd > PROVIDER_DATE ? list.gecontroleerd : PROVIDER_DATE, mainEntityOfPage: canon(slug), author: { '@id': SITE.base + '#org' }, publisher: { '@id': SITE.base + '#org' },
      about: { '@type': organizationEntity ? 'MedicalClinic' : k.kind === 'doctor' ? 'Physician' : 'MedicalClinic', name, ...(/^https?:\/\//.test(k.site || '') ? { url: k.site } : {}), address: { '@type': 'PostalAddress', ...(k.stad ? { addressLocality: k.stad } : {}), addressCountry: k.land || list.land } },
      citation: [...new Set([...included.map(r => r.bron), o.prijs_bron, o.arts_bron, ...risks.map(r => r.bron)].filter(Boolean))] },
    { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: t.home, item: canon(language === 'en' ? '' : language) }, { '@type': 'ListItem', position: 2, name: rankTitle, item: canon(rankSlug) }, { '@type': 'ListItem', position: 3, name: short, item: canon(slug) }] },
    { '@type': 'FAQPage', mainEntity: faq.map(f => ({ '@type': 'Question', name: f.q, acceptedAnswer: { '@type': 'Answer', text: f.a } })) }] };
  return { title, desc, body, ld, alts: LANGS.map(tl => [slugs[tl], tl]), faq, pseudo: { ingreep: list.ingreep, naar: list.naar, faq } };
}

// ---- geschreven samenvatting boven een ranglijst (ook de ingreeppagina's) ----
const S = {
  en: { lead: (date, c, d, rc, rd) => `Read on ${date}: this selection holds ${c} ${c === 1 ? 'clinic' : 'clinics'} and ${d} ${d === 1 ? 'doctor' : 'doctors'} with their own review profile. Enough public reviews for a numbered place: ${rc} ${rc === 1 ? 'clinic' : 'clinics'} and ${rd} ${rd === 1 ? 'doctor' : 'doctors'}.`, top: 'Highest review index', excluded: (n, platform, score) => `${n} also has a ${platform} profile showing ${score}/5 without a readable review count, so it does not count in the index.`, price: (n, total) => `${n} of ${total} providers publish a price on their own site.`, warn: 'A review platform removed fake reviews or suspended the profile at', incident: 'A regulator action, reported incident or open complaint is recorded at', see: 'see the entry', limit: 'The index measures public reviews, not safety or the result of a treatment.', countries: n => `The selection covers ${n} countries.` },
  nl: { lead: (date, c, d, rc, rd) => `Gelezen op ${date}: deze selectie telt ${c} ${c === 1 ? 'kliniek' : 'klinieken'} en ${d} ${d === 1 ? 'arts' : 'artsen'} met een eigen reviewprofiel. Genoeg openbare reviews voor een genummerde plek: ${rc} ${rc === 1 ? 'kliniek' : 'klinieken'} en ${rd} ${rd === 1 ? 'arts' : 'artsen'}.`, top: 'Hoogste review-index', excluded: (n, platform, score) => `${n} heeft ook een ${platform}-profiel met ${score}/5 zonder leesbaar aantal reviews; dat telt daarom niet mee in de index.`, price: (n, total) => `${n} van de ${total} aanbieders zetten een prijs op hun eigen site.`, warn: 'Een reviewplatform verwijderde nepreviews of schorste het profiel bij', incident: 'Een maatregel van een toezichthouder, gemeld incident of lopende klacht staat bij', see: 'zie de vermelding', limit: 'De index meet openbare reviews, niet de veiligheid of het resultaat van een behandeling.', countries: n => `De selectie beslaat ${n} landen.` },
  de: { lead: (date, c, d, rc, rd) => `Gelesen am ${date}: Diese Auswahl umfasst ${c} ${c === 1 ? 'Klinik' : 'Kliniken'} und ${d} ${d === 1 ? 'Arzt' : 'Ärzte'} mit eigenem Bewertungsprofil. Genug öffentliche Bewertungen für einen nummerierten Platz: ${rc} ${rc === 1 ? 'Klinik' : 'Kliniken'} und ${rd} ${rd === 1 ? 'Arzt' : 'Ärzte'}.`, top: 'Höchster Bewertungsindex', excluded: (n, platform, score) => `${n} hat außerdem ein ${platform}-Profil mit ${score}/5 ohne lesbare Anzahl; es zählt deshalb nicht im Index.`, price: (n, total) => `${n} von ${total} Anbietern veröffentlichen einen Preis auf der eigenen Website.`, warn: 'Eine Bewertungsplattform entfernte gefälschte Bewertungen oder sperrte das Profil bei', incident: 'Eine Aufsichtsmaßnahme, ein gemeldeter Vorfall oder eine offene Beschwerde steht bei', see: 'siehe Eintrag', limit: 'Der Index misst öffentliche Bewertungen, nicht die Sicherheit oder das Ergebnis einer Behandlung.', countries: n => `Die Auswahl umfasst ${n} Länder.` },
};
// Beschrijving voor zoekresultaten: 140 tot 160 tekens, met echte cijfers van de pagina in plaats van een vaste zin.
const knip = (tekst, max = 160) => { const x = String(tekst).replace(/\s+/g, ' ').trim(); if (x.length <= max) return x; const cut = x.slice(0, max + 1), punt = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('; ')); return (punt > 90 ? cut.slice(0, punt + 1) : cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:]$/, '') + '.'); };
const RD = {
  en: (name, n, top, date) => `${name}: ${n} clinics and doctors compared on public reviews. Highest review index: ${top}. With source figures, prices and who operates. Read on ${date}.`,
  nl: (name, n, top, date) => `${name}: ${n} klinieken en artsen vergeleken op openbare reviews. Hoogste review-index: ${top}. Met broncijfers, prijzen en wie opereert. Gelezen op ${date}.`,
  de: (name, n, top, date) => `${name}: ${n} Kliniken und Ärzte nach öffentlichen Bewertungen verglichen. Höchster Bewertungsindex: ${top}. Mit Quellenzahlen, Preisen und wer operiert. Gelesen am ${date}.`,
};
export function rankDescription(list, language) {
  const clinics = reviewRanking(list), doctors = reviewRanking(list, 'doctor'), lead = doctors.ranked.length > clinics.ranked.length ? doctors : clinics;
  const name = choiceTitle(list, language).split(': ')[0], n = clinics.ranked.length + clinics.unranked.length + doctors.ranked.length + doctors.unranked.length;
  if (!lead.ranked.length) return '';
  for (const count of [3, 2, 1]) { const top = lead.ranked.slice(0, count).map(r => `${kort(r.k.naam)} ${num(r.review.score, language)}`).join(', '), text = (RD[language] || RD.en)(name, n, top, list.gecontroleerd); if (text.length <= 165 || count === 1) return knip(text, 165); }
}
const joinNames = (names, t) => names.length < 2 ? names.join('') : names.slice(0, -1).join(', ') + ' ' + t.and + ' ' + names.at(-1);
export function rankSummary(base, list, language) {
  const s = S[language], t = T[language], clinics = reviewRanking(list), doctors = reviewRanking(list, 'doctor');
  const lead = doctors.ranked.length > clinics.ranked.length ? doctors : clinics, top = lead.ranked.slice(0, 3);
  if (!top.length) return '';
  const pages = new Map(providerEntries().map(e => [e.list.id + '|' + e.provider.id, e]));
  const link = k => { const e = pages.get((k.list_id || list.id) + '|' + String(k.id).replace(/-doctor-\d+$/, '')); return e ? `<a href="${esc(url(base, e.slugs[language]))}">${esc(k.naam)}</a>` : esc(k.naam); };
  const src = r => r.review.sources.included.map(x => `${x.platform} ${String(x.score).replace('.', language === 'en' ? '.' : ',')}/${x.max}, ${x.aantal}`).join('; ');
  const first = top[0], odd = first.review.sources.excluded.find(x => x.reason === 'unavailable_or_invalid' && x.score != null && x.platform);
  const records = list.klinieken || [], priced = records.filter(k => k.openheid && k.openheid.prijs).length;
  const warned = records.filter(k => (k.reviews || []).some(r => waarschuwingTekst(r.waarschuwing, language)));
  const incidents = records.filter(k => (k.risico || []).some((r, i) => r.bron && veldTekst(k.list_id || list.id, k.id, 'risico:' + i, language)));
  const countries = new Set(records.map(k => k.land || list.land).filter(Boolean)).size;
  const parts = [
    `<p>${esc(s.lead(list.gecontroleerd, clinics.ranked.length + clinics.unranked.length, doctors.ranked.length + doctors.unranked.length, clinics.ranked.length, doctors.ranked.length))}${countries > 2 ? ' ' + esc(s.countries(countries)) : ''}</p>`,
    `<p><strong>${esc(s.top)}:</strong> ${top.map((r, i) => `${i + 1}. ${link(r.k)} ${num(r.review.score, language)} (${esc(src(r))})`).join(' · ')}.${odd ? ' ' + esc(s.excluded(first.k.naam, odd.platform, String(odd.score).replace('.', language === 'en' ? '.' : ','))) : ''}</p>`,
    priced ? `<p>${esc(s.price(priced, records.length))}</p>` : '',
    warned.length ? `<p>${esc(s.warn)} ${joinNames(warned.map(link), t)}.</p>` : '',
    incidents.length ? `<p>${esc(s.incident)} ${joinNames(incidents.map(link), t)}.</p>` : '',
    `<p class="sr-muted">${esc(s.limit)}</p>`];
  return `<div class="answer" id="samenvatting">${parts.join('')}</div>`;
}

