export const DATA_SLUGS = () => Object.fromEntries(Object.entries(D).flatMap(([kind, d]) => LANGS.map(language => [d.slugs[language], { kind, taal: language }])));
export function dataPage(base, kind, language) {
  const d = D[kind], c = d[language], t = T[language], pages = new Map(providerEntries().map(e => [e.list.id + '|' + e.provider.id, e]));
  const naam = (list, k) => { const e = pages.get(list.id + '|' + k.id); return e ? `<a href="${esc(url(base, e.slugs[language]))}">${esc(k.naam)}</a>` : esc(k.naam); };
  const rows = [];
  for (const list of BASE_LISTS()) {
    if (kind === 'warnings') for (const k of list.klinieken || []) for (const r of k.reviews || []) { const w = waarschuwingTekst(r.waarschuwing, language); if (w) rows.push([naam(list, k), ext(r.bron, r.platform), esc(w), esc(r.datum || list.gecontroleerd)]); }
    if (kind === 'incidents') {
      for (const k of list.klinieken || []) (k.risico || []).forEach((r, i) => { const tekst = veldTekst(list.id, k.id, 'risico:' + i, language); if (tekst && r.bron) rows.push([naam(list, k), esc(countryName(k.land || list.land, language)), esc(tekst), ext(r.bron, host(r.bron)) + (r.datum ? ' · ' + esc(r.datum) : '')]); });
      for (const x of list.niet_gerangschikt || []) { const b = BUITEN_RANGLIJST[x.naam]; if (b && b.incident && b[language] && x.bron) rows.push([esc(x.naam), esc(countryName(list.land, language)), esc(b[language]), ext(x.bron, host(x.bron))]); }
    }
  }
  const unique = rows.filter((r, i) => rows.findIndex(x => x.join('|') === r.join('|')) === i), n = new Set(unique.map(r => r[0])).size;
  const slug = d.slugs[language], date = BASE_LISTS().map(l => l.gecontroleerd).sort().at(-1);
  const body = `<div class="s-choice pv"><p class="sr-breadcrumb"><a href="${esc(url(base, language === 'en' ? '' : language))}">${esc(t.home)}</a></p><h1>${esc(c.h1)}</h1><div class="answer"><p>${esc(c.lead(n))}</p></div><p class="sr-muted"><time datetime="${esc(date)}">${esc(t.read)} ${esc(date)}</time></p><div class="sr-table"><table><thead><tr>${c.cols.map(h => '<th>' + esc(h) + '</th>').join('')}</tr></thead><tbody>${unique.map(r => `<tr><th scope="row">${r[0]}</th>${r.slice(1).map(x => '<td>' + x + '</td>').join('')}</tr>`).join('')}</tbody></table></div><h2>${esc(c.what)}</h2><p>${esc(c.whatP)}</p><h2>${esc(c.how)}</h2><p>${esc(c.howP)}</p><h2>${esc(t.more)}</h2><ul>${BASE_LISTS().map(l => `<li><a href="${esc(url(base, l.slugs[language] || l.slugs.en))}">${esc(choiceTitle(l, language))}</a></li>`).join('')}<li><a href="${esc(url(base, D[kind === 'warnings' ? 'incidents' : 'warnings'].slugs[language]))}">${esc(D[kind === 'warnings' ? 'incidents' : 'warnings'][language].h1)}</a></li></ul><p class="sr-note">${esc(t.limits)} <a href="${esc(url(base, aboutSlug(language)))}">${esc(t.method)}</a>. ${esc(t.correction)} <a href="mailto:${CONTACT}">${CONTACT}</a>.</p><!--sc-mail--></div>`;
  const ld = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'Organization', '@id': SITE.base + '#org', name: SITE.name, url: SITE.base },
    { '@type': 'Article', headline: c.h1, description: c.lead(n), inLanguage: language, datePublished: PROVIDER_DATE, dateModified: date > PROVIDER_DATE ? date : PROVIDER_DATE, mainEntityOfPage: canon(slug), author: { '@id': SITE.base + '#org' }, publisher: { '@id': SITE.base + '#org' } },
    { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: t.home, item: canon(language === 'en' ? '' : language) }, { '@type': 'ListItem', position: 2, name: c.h1, item: canon(slug) }] }] };
  return { title: c.title, desc: knip(c.lead(n)), body, ld, alts: LANGS.map(tl => [d.slugs[tl], tl]), rows: unique.length };
}

