export const aboutSlug = language => ABOUT[language].slug;
export const ABOUT_SLUGS = () => Object.fromEntries(LANGS.map(language => [ABOUT[language].slug, language]));
export function aboutPage(base, language) {
  const a = ABOUT[language], t = T[language];
  const body = `<div class="s-choice pv"><p class="sr-breadcrumb"><a href="${esc(url(base, language === 'en' ? '' : language))}">${esc(t.home)}</a></p><h1>${esc(a.h1)}</h1>${a.secties.map(([h, p]) => `<h2>${esc(h)}</h2><p>${esc(p).replace(CONTACT, `<a href="mailto:${CONTACT}">${CONTACT}</a>`).replace('adsfair.xyz', '<a href="https://adsfair.xyz">adsfair.xyz</a>')}</p>`).join('')}<h2>${esc(t.more)}</h2><ul><li><a href="${esc(url(base, catalogSlug(language)))}">${esc(language === 'nl' ? 'Alle ingrepen' : language === 'de' ? 'Alle Behandlungen' : 'All procedures')}</a></li>${Object.values(D).map(d => `<li><a href="${esc(url(base, d.slugs[language]))}">${esc(d[language].h1)}</a></li>`).join('')}</ul></div>`;
  const ld = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'Organization', '@id': SITE.base + '#org', name: SITE.name, url: SITE.base, email: CONTACT, parentOrganization: { '@type': 'Organization', '@id': 'https://adsfair.xyz/#org', name: 'AdsFair B.V.', url: 'https://adsfair.xyz', foundingDate: '2014-02-26', founder: { '@type': 'Person', '@id': 'https://adsfair.xyz/#founder', name: 'Henkjan de Krijger', sameAs: ['https://www.linkedin.com/in/henkjandekrijger'] }, address: { '@type': 'PostalAddress', streetAddress: 'Albert Plesmanplein 20', postalCode: '2805 AB', addressLocality: 'Gouda', addressCountry: 'NL' } } },
    { '@type': 'AboutPage', name: a.title, url: canon(a.slug), inLanguage: language, dateModified: PROVIDER_DATE, publisher: { '@id': SITE.base + '#org' } }] };
  return { title: a.title, desc: knip(a.secties[0][1]), body, ld, alts: LANGS.map(tl => [ABOUT[tl].slug, tl]) };
}

// ---- twee aanbieders naast elkaar (hooguit een handvol paren waar mensen echt op zoeken; geen pagina per combinatie) ----
const PAIRS = [['hair-turkey', 'smile', 'vera'], ['hair-turkey', 'cosmedica', 'asmed'], ['hair-turkey', 'estenove', 'hermest'], ['hair-turkey', 'clinicana', 'smile'], ['hair-turkey', 'elithair', 'cinik']];
const VS = { en: 'compare', nl: 'nl/vergelijk', de: 'de/vergleich' };
const V = {
  en: { title: (a, b) => `${a} vs ${b}: reviews, prices and who operates`, lead: 'Both sides come from the same sources, read on the same date. Where a field is empty, the provider does not publish it.', row: { index: 'Review index', place: 'Place in our ranking', reviews: 'Review figures', price: 'Published prices', who: 'Who operates', guarantee: 'Guarantee and aftercare', doctors: 'Doctors named', incidents: 'Reported incidents' }, none: 'Not published', noPlace: 'No numbered place', noIncident: 'None found in our sources', diff: 'What differs', page: 'Full page', of: 'of' },
  nl: { title: (a, b) => `${a} of ${b}: ervaringen, prijzen en wie opereert`, lead: 'Beide kanten komen uit dezelfde bronnen, gelezen op dezelfde datum. Is een veld leeg, dan publiceert de aanbieder het niet.', row: { index: 'Review-index', place: 'Plek in onze ranglijst', reviews: 'Reviewcijfers', price: 'Gepubliceerde prijzen', who: 'Wie opereert', guarantee: 'Garantie en nazorg', doctors: 'Genoemde artsen', incidents: 'Gemelde incidenten' }, none: 'Niet gepubliceerd', noPlace: 'Geen genummerde plek', noIncident: 'Geen gevonden in onze bronnen', diff: 'Wat verschilt', page: 'Volledige pagina', of: 'van' },
  de: { title: (a, b) => `${a} oder ${b}: Erfahrungen, Preise und wer operiert`, lead: 'Beide Seiten stammen aus denselben Quellen, gelesen am selben Datum. Ist ein Feld leer, veröffentlicht der Anbieter es nicht.', row: { index: 'Bewertungsindex', place: 'Platz in unserer Rangliste', reviews: 'Bewertungszahlen', price: 'Veröffentlichte Preise', who: 'Wer operiert', guarantee: 'Garantie und Nachsorge', doctors: 'Genannte Ärzte', incidents: 'Gemeldete Vorfälle' }, none: 'Nicht veröffentlicht', noPlace: 'Kein nummerierter Platz', noIncident: 'Keine in unseren Quellen gefunden', diff: 'Was sich unterscheidet', page: 'Vollständige Seite', of: 'von' },
};
const pairEntries = () => PAIRS.map(([listId, a, b]) => { const find = id => providerEntries().find(e => e.list.id === listId && e.provider.id === id), x = find(a), y = find(b); return x && y ? { x, y, slugs: Object.fromEntries(LANGS.map(language => [language, VS[language] + '/' + x.slugs.en.split('/').pop() + '-vs-' + y.slugs.en.split('/').pop()])) } : null; }).filter(Boolean);
export const COMPARE_SLUGS = () => Object.fromEntries(pairEntries().flatMap(pair => LANGS.map(language => [pair.slugs[language], { pair, taal: language }])));
export function comparePage(base, pair, language) {
  const v = V[language], t = T[language], list = pair.x.list, sides = [pair.x, pair.y], names = sides.map(e => kort(e.provider.naam)), slug = pair.slugs[language];
  const rankSlug = list.slugs[language] || list.slugs.en, rankTitle = choiceTitle(list, language).split(': ')[0];
  const data = sides.map(e => { const k = e.provider, pos = position(list, k), all = pos.review ? [...pos.review.sources.included, ...pos.review.sources.excluded].filter(r => r.score != null && r.aantal != null && r.platform) : [];
    return { e, k, pos, index: pos.cohort ? num(pos.review.score, language) + '/5' : '', place: pos.cohort && pos.total >= 3 ? `${pos.place} ${v.of} ${pos.total}` : v.noPlace,
      reviews: all.map(r => `${r.platform} ${String(r.score).replace('.', language === 'en' ? '.' : ',')}/${r.max || 5} (${r.aantal})`).join(', '), price: veldTekst(list.id, k.id, 'prijs', language), who: veldTekst(list.id, k.id, 'arts', language), guarantee: veldTekst(list.id, k.id, 'gar', language),
      doctors: (k.artsen || []).filter(a => a.naam && a.bron).map(a => a.naam).join(', '), incidents: (k.risico || []).map((r, i) => veldTekst(list.id, k.id, 'risico:' + i, language)).filter(Boolean).join(' ') }; });
  const rows = [['index', d => d.index || v.noPlace], ['place', d => d.place], ['reviews', d => d.reviews || t.noReviews], ['price', d => d.price || v.none], ['who', d => d.who || v.none], ['guarantee', d => d.guarantee || v.none], ['doctors', d => d.doctors || v.none], ['incidents', d => d.incidents || v.noIncident]];
  const faq = sides.map((e, i) => ({ q: t.qLegit(names[i]), a: `${data[i].reviews || t.noReviews.replace(/\.$/, '')}. ${data[i].index ? t.index + ' ' + data[i].index + '.' : v.noPlace + '.'} ${t.read} ${list.gecontroleerd}.` }));
  const body = `<div class="s-choice pv"><p class="sr-breadcrumb"><a href="${esc(url(base, language === 'en' ? '' : language))}">${esc(t.home)}</a> / <a href="${esc(url(base, rankSlug))}">${esc(rankTitle)}</a></p><h1>${esc(v.title(names[0], names[1]))}</h1><p class="sr-muted"><time datetime="${esc(list.gecontroleerd)}">${esc(t.read)} ${esc(list.gecontroleerd)}</time> · ${esc(v.lead)}</p>` +
    `<div class="answer">${sides.map((e, i) => `<p><strong>${esc(names[i])}.</strong> ${esc(conclusieTekst(list.id, e.provider, language))}</p>`).join('')}</div>` +
    `<h2>${esc(v.diff)}</h2><div class="sr-table"><table><thead><tr><th></th>${sides.map((e, i) => `<th><a href="${esc(url(base, e.slugs[language]))}">${esc(names[i])}</a></th>`).join('')}</tr></thead><tbody>${rows.map(([key, get]) => `<tr><th scope="row">${esc(v.row[key])}</th>${data.map(d => '<td>' + esc(get(d)) + '</td>').join('')}</tr>`).join('')}</tbody></table></div>` +
    `<h2>${esc(t.more)}</h2><ul>${sides.map((e, i) => `<li><a href="${esc(url(base, e.slugs[language]))}">${esc(v.page)}: ${esc(e.provider.naam)}</a></li>`).join('')}<li><a href="${esc(url(base, rankSlug))}">${esc(t.ranking)}: ${esc(rankTitle)}</a></li>${pairEntries().filter(p => p.slugs.en !== pair.slugs.en && (p.x === pair.x || p.y === pair.x || p.x === pair.y || p.y === pair.y)).map(p => `<li><a href="${esc(url(base, p.slugs[language]))}">${esc(v.title(kort(p.x.provider.naam), kort(p.y.provider.naam)).split(':')[0])}</a></li>`).join('')}</ul>` +
    `<section id="vragen"><h2>${esc(t.faq)}</h2>${faq.map(f => `<details><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join('')}</section>` +
    `<p class="sr-note">${esc(t.limits)} <a href="${esc(url(base, aboutSlug(language)))}">${esc(t.method)}</a>. ${esc(t.correction)} <a href="mailto:${CONTACT}">${CONTACT}</a>.</p><!--sc-help--><!--sc-mail--></div>`;
  const lang = v.title(names[0], names[1]), title = lang.length <= 60 ? lang : lang.split(':')[0] + ': ' + (language === 'nl' ? 'ervaringen en prijzen' : language === 'de' ? 'Erfahrungen und Preise' : 'reviews and prices'), desc = knip(`${title.split(':')[0]}: ${data.map((d, i) => names[i] + ' ' + (d.index || v.noPlace)).join(', ')}. ${v.lead}`);
  const ld = { '@context': 'https://schema.org', '@graph': [
    { '@type': 'Organization', '@id': SITE.base + '#org', name: SITE.name, url: SITE.base },
    { '@type': 'Article', headline: title, description: desc, inLanguage: language, datePublished: PROVIDER_DATE, dateModified: list.gecontroleerd > PROVIDER_DATE ? list.gecontroleerd : PROVIDER_DATE, mainEntityOfPage: canon(slug), author: { '@id': SITE.base + '#org' }, publisher: { '@id': SITE.base + '#org' } },
    { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: t.home, item: canon(language === 'en' ? '' : language) }, { '@type': 'ListItem', position: 2, name: rankTitle, item: canon(rankSlug) }, { '@type': 'ListItem', position: 3, name: title.split(':')[0], item: canon(slug) }] },
    { '@type': 'FAQPage', mainEntity: faq.map(f => ({ '@type': 'Question', name: f.q, acceptedAnswer: { '@type': 'Answer', text: f.a } })) }] };
  return { title, desc, body, ld, alts: LANGS.map(tl => [pair.slugs[tl], tl]), faq, pseudo: { ingreep: list.ingreep, naar: list.naar, faq } };
}
// Vergelijkingen waarin deze aanbieder voorkomt (voor de links op zijn eigen pagina).
export const compareLinks = (base, entry, language) => pairEntries().filter(p => p.x === entry || p.y === entry).map(p => `<li><a href="${esc(url(base, p.slugs[language]))}">${esc(V[language].title(kort(p.x.provider.naam), kort(p.y.provider.naam)).split(':')[0])}</a></li>`).join('');

// ---- voor de ochtendmail: de drie hoogste van een gekozen ingreep, met cijfers en een link per aanbieder ----
const M = { en: 'Highest review index now', nl: 'Hoogste review-index nu', de: 'Höchster Bewertungsindex jetzt' };
export function mailTopThree(topics, language, link) {
  const pages = new Map(providerEntries().map(e => [e.list.id + '|' + e.provider.id, e]));
  return (topics || []).slice(0, 2).map(topic => {
    const list = LIJSTEN['procedure-' + topic]; if (!list) return '';
    const clinics = reviewRanking(list), doctors = reviewRanking(list, 'doctor'), top = (doctors.ranked.length > clinics.ranked.length ? doctors : clinics).ranked.slice(0, 3);
    if (!top.length) return '';
    const slug = list.slugs[language] || list.slugs.en;
    return `<h2 style="font-size:18px">${esc(procedureLabel(topic, language))}: ${esc(M[language] || M.en)}</h2><ol>${top.map(r => { const e = pages.get((r.k.list_id || '') + '|' + String(r.k.id).replace(/-doctor-\d+$/, '')), href = e ? link(e.slugs[language]) : link(slug) + '#k-' + String(r.k.id || r.k.naam).replace(/[^a-zA-Z0-9_-]/g, '-');
      return `<li><a href="${esc(href)}">${esc(r.k.naam)}</a> · ${num(r.review.score, language)}/5 · ${esc([countryName(r.k.land || list.land, language), ...r.review.sources.included.map(x => `${x.platform} ${String(x.score).replace('.', language === 'en' ? '.' : ',')}/${x.max} (${x.aantal})`)].filter(Boolean).join(' · '))}</li>`; }).join('')}</ol><p style="font-size:13px"><a href="${esc(link(slug))}">${esc(T[language].ranking)}: ${esc(procedureLabel(topic, language))}</a> · ${esc(T[language].read)} ${esc(list.gecontroleerd)}</p>`;
  }).join('');
}

